script:
frappe.ui.form.on('Email Account', {
	refresh(frm) {
// 		if (frm.doc.enable_outgoing) {
			site_name = window.location.hostname;
			uninstall_link = `https://cloud.frappe.io/dashboard/sites/${site_name}/apps`;
			eds_a_tag = `<a style='text-decoration: underline;' href='https://cloud.frappe.io/marketplace/apps/email_delivery_service'>Email Delivery Service</a>`;
			//make a head request to /api/method/ping and check if response has server header set as 'Frappe Cloud'
			is_frappe_cloud = fetch('/api/method/ping', { method: 'HEAD' }).then(
				(response) => {
					if (response.headers.get('server') === 'Frappe Cloud') {
						return true;
					}
					return false;
				},
			);
			uninstall_a_tag = `<a style='text-decoration: underline;' href='${uninstall_link}'>uninstall the app</a>`;
			if (!is_frappe_cloud) {
				uninstall_a_tag = 'uninstall the app';
			}
			frm.dashboard.set_headline_alert(
				__(
					`You have ${eds_a_tag} app installed due to which emails won't be sent from this account. Please ${uninstall_a_tag} to use current Email Account for sending.`,
				),
				'yellow',
			);
// 		}
	},
});

// ==========================================================
// SHIPMENT FORM
// ==========================================================

frappe.ui.form.on("Shipment", {

    refresh(frm) {

        renumber_inner_boxes(frm);
        renumber_outer_boxes(frm);

        frm.add_custom_button(__('Fetch Items from Delivery Note'), function () {

            if (!frm.doc.delivery_customer) {
                frappe.msgprint(__('Please select Delivery Customer first'));
                return;
            }

            frappe.prompt(
                [
                    {
                        fieldname: 'delivery_note',
                        fieldtype: 'Link',
                        options: 'Delivery Note',
                        label: 'Delivery Note',
                        reqd: 1,
                        get_query: function () {
                            return {
                                filters: {
                                    customer: frm.doc.delivery_customer,
                                    docstatus: 1
                                }
                            };
                        }
                    }
                ],
                function (values) {

                    frappe.call({
                        method: "Get Delivery Note Items",
                        args: {
                            delivery_note: values.delivery_note
                        },
                        freeze: true,
                        callback: function (r) {

                            if (!r.message || !r.message.length) return;

                            const dialog = new frappe.ui.Dialog({
                                title: __('Select Items'),
                                size: 'extra-large',
                                fields: [
                                    {
                                        fieldname: 'items',
                                        fieldtype: 'Table',
                                        cannot_add_rows: true,
                                        data: r.message.map(d => ({
                                            select: 1,
                                            delivery_note: d.delivery_note,
                                            item_code: d.item_code,
                                            item_name: d.item_name,
                                            description: strip_html(d.description),
                                            qty: flt(d.qty) || 0,   // ✅ FIXED
                                            uom: d.uom
                                        })),
                                        fields: [
                                            { fieldtype: 'Check', fieldname: 'select', label: 'Select', in_list_view: 1 },
                                            { fieldtype: 'Data', fieldname: 'delivery_note', label: 'Delivery Note', read_only: 1, in_list_view: 1 },
                                            { fieldtype: 'Data', fieldname: 'item_code', label: 'Item Code', read_only: 1, in_list_view: 1 },
                                            { fieldtype: 'Data', fieldname: 'item_name', label: 'Item Name', read_only: 1, in_list_view: 1 },
                                            { fieldtype: 'Data', fieldname: 'description', label: 'Description', read_only: 1, in_list_view: 1 },
                                            { fieldtype: 'Float', fieldname: 'qty', label: 'Qty', in_list_view: 1 },
                                            { fieldtype: 'Data', fieldname: 'uom', label: 'UOM', read_only: 1, in_list_view: 1 }
                                        ]
                                    }
                                ],

                                primary_action_label: __('Add to Shipment'),

                                primary_action(values) {

                                    const selected = (values.items || []).filter(
                                        row => row.select && row.qty > 0
                                    );

                                    if (!selected.length) {
                                        frappe.msgprint(__('Please select at least one item'));
                                        return;
                                    }

                                    selected.forEach(row => {

                                        let child = frm.add_child('custom_shipment_box');

                                        child.delivery_note = row.delivery_note;
                                        child.item_code = row.item_code;
                                        child.item_description = row.description;
                                        child.qty = row.qty;
                                        child.packed = 0;
                                        child.net_weight = 0;
                                        child.gross_weight = 0;
                                    });

                                    frm.refresh_field('custom_shipment_box');
                                    renumber_inner_boxes(frm);

                                    dialog.hide();
                                }
                            });

                            dialog.show();

                            // ✅ FORCE GRID REFRESH (important for qty display)
                            dialog.fields_dict.items.grid.refresh();

                            // ✅ ENABLE SCROLL
                            dialog.$wrapper.find('.modal-body').css({
                                'max-height': '75vh',
                                'overflow-y': 'auto'
                            });

                            dialog.$wrapper.find('.grid-body').css({
                                'overflow-x': 'auto'
                            });
                        }
                    });

                },
                __('Select Delivery Note'),
                __('Fetch')
            );

        });

    },

    before_save(frm) {

        renumber_inner_boxes(frm);
        renumber_outer_boxes(frm);

        (frm.doc.custom_outer_box || []).forEach(row => {
            calculate_outer_box(frm, row.doctype, row.name);
        });
    }
});


// ==========================================================
// STRIP HTML FUNCTION
// ==========================================================

function strip_html(html) {
    if (!html) return "";
    return html.replace(/<\/?[^>]+(>|$)/g, "").trim();
}


// ==========================================================
// INNER BOX AUTO NUMBERING
// ==========================================================

frappe.ui.form.on("Shipment Box", {

    custom_shipment_box_add(frm) {
        renumber_inner_boxes(frm);
    },

    custom_shipment_box_remove(frm) {
        renumber_inner_boxes(frm);
    },

    gross_weight(frm, cdt, cdn) {
        validate_weight(frm, cdt, cdn);
    },

    net_weight(frm, cdt, cdn) {
        validate_weight(frm, cdt, cdn);
    }
});

function renumber_inner_boxes(frm) {
    if (!frm.doc.custom_shipment_box) return;

    frm.doc.custom_shipment_box.forEach((row, index) => {
        row.inner_box_no = "P-" + (index + 1);
    });

    frm.refresh_field("custom_shipment_box");
}


// ==========================================================
// OUTER BOX AUTO NUMBERING
// ==========================================================

frappe.ui.form.on("Shipment Outer Box", {

    custom_outer_box_add(frm) {
        renumber_outer_boxes(frm);
    },

    custom_outer_box_remove(frm) {
        renumber_outer_boxes(frm);
    },

    inner_boxes(frm, cdt, cdn) {
        calculate_outer_box(frm, cdt, cdn);
    },

    box_template(frm, cdt, cdn) {
        calculate_outer_box(frm, cdt, cdn);
    }
});

function renumber_outer_boxes(frm) {
    if (!frm.doc.custom_outer_box) return;

    frm.doc.custom_outer_box.forEach((row, index) => {
        row.outer_box_no = "S-" + (index + 1);
    });

    frm.refresh_field("custom_outer_box");
}


// ==========================================================
// OUTER BOX WEIGHT CALCULATION
// ==========================================================

function calculate_outer_box(frm, cdt, cdn) {

    let row = locals[cdt][cdn];
    let total_gross_weight = 0;
    let total_net_weight = 0;

    let inner_boxes = [];

    if (row.inner_box) {
        if (Array.isArray(row.inner_box)) {
            inner_boxes = row.inner_box;
        } else if (typeof row.inner_box === "string") {
            inner_boxes = row.inner_box.split(",").map(d => d.trim());
        }
    }

    (frm.doc.custom_shipment_box || []).forEach(inner => {
        if (inner_boxes.includes(inner.inner_box_no)) {
            total_gross_weight += flt(inner.gross_weight || 0);
            total_net_weight += flt(inner.net_weight || 0);
        }
    });

    if (row.box_template) {
        frappe.db.get_value(
            "Shipment Parcel Template",
            row.box_template,
            "weight",
            function(r) {
                let template_weight = r ? flt(r.weight) : 0;
                row.gross_weight = total_gross_weight + template_weight;
                row.net_weight = total_net_weight;
                frm.refresh_field("custom_outer_box");
            }
        );
    } else {
        row.gross_weight = total_gross_weight;
        row.net_weight = total_net_weight;
        frm.refresh_field("custom_outer_box");
    }
}


// ==========================================================
// INNER BOX WEIGHT VALIDATION
// ==========================================================

function validate_weight(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    if (row.net_weight && row.gross_weight) {
        if (flt(row.net_weight) > flt(row.gross_weight)) {

            frappe.msgprint({
                title: __('Invalid Weight'),
                message: __('Net Weight cannot be greater than Gross Weight'),
                indicator: 'red'
            });

            row.net_weight = 0;
            frm.refresh_field("custom_shipment_box");
        }
    }
}

frappe.ui.form.on("Shipment Outer Box", {
    select_inner_boxes(frm, cdt, cdn) {
        const ob = locals[cdt][cdn];

        const boxes = (frm.doc.custom_shipment_box || []).map(b => ({
            label: `${b.inner_box_no} (GW: ${b.gross_weight}, NW: ${b.net_weight})`,
            value: b.inner_box_no
        }));

        if (!boxes.length) {
            frappe.msgprint("No Inner Boxes available");
            return;
        }

        const dialog = new frappe.ui.Dialog({
            title: __("Select Inner Boxes"),
            fields: [{
                fieldtype: "MultiCheck",
                fieldname: "inner_boxes",
                label: "Inner Boxes",
                options: boxes
            }],
            primary_action_label: __("Update Outer Box"),
            primary_action(values) {
                const selected = values.inner_boxes || [];

                if (!selected.length) {
                    frappe.msgprint("Select at least one Inner Box");
                    return;
                }

                let gross = 0;
                let net = 0;

                // Reset previous mapping for this outer box
                (frm.doc.custom_shipment_box || []).forEach(b => {
                    if (b.outer_box === ob.outer_box_no) {
                        b.outer_box = "";
                    }
                });

                // Map selected inner boxes
                (frm.doc.custom_shipment_box || []).forEach(b => {
                    if (selected.includes(b.inner_box_no)) {
                        b.outer_box = ob.outer_box_no;
                        gross += flt(b.gross_weight);
                        net += flt(b.net_weight);
                    }
                });

                // ✅ UPDATE Shipment Outer Box
                frappe.model.set_value(cdt, cdn, "inner_box", selected.join(", "));
                frappe.model.set_value(cdt, cdn, "gross_weight", gross);
                frappe.model.set_value(cdt, cdn, "net_weight", net);

                frm.refresh_field("custom_shipment_box");
                frm.refresh_field("custom_outer_box");

                dialog.hide();
            }
        });

        dialog.show();
    }
});

frappe.ui.form.on("Shipment", {
    refresh(frm) {

        frm.add_custom_button(__('Fetch Items from Purchase Order'), () => {

            frappe.prompt(
                [
                    {
                        fieldname: 'purchase_order',
                        fieldtype: 'Link',
                        options: 'Purchase Order',
                        label: 'Purchase Order',
                        reqd: 1,
                        get_query: () => {
                            return {
                                filters: {
                                    docstatus: 1
                                }
                            };
                        }
                    }
                ],

                function(values) {

                    let selected_po = values.purchase_order;

                    frappe.call({
                        method: "get_purchase_order_items",
                        args: {
                            purchase_order: selected_po
                        },

                        callback: function(r) {

                            let po_items = r.message || [];

                            if (!po_items.length) {
                                frappe.msgprint(__('No items available for this Purchase Order'));
                                return;
                            }

                            const dialog = new frappe.ui.Dialog({
                                title: __('Select Items from Purchase Order'),
                                size: 'large',

                                fields: [
                                    {
                                        fieldname: 'items',
                                        fieldtype: 'Table',
                                        cannot_add_rows: true,
                                        in_place_edit: true,

                                        data: po_items.map(d => ({
                                            select: 1,
                                            item_code: d.item_code,
                                            item_name: d.item_name,
                                            description: d.description,
                                            qty: d.qty,
                                            uom: d.uom
                                        })),

                                        fields: [
                                            {fieldtype:'Check', fieldname:'select', in_list_view:1},
                                            {fieldtype:'Data', fieldname:'item_code', label:'Item Code', read_only:1, in_list_view:1},
                                            {fieldtype:'Data', fieldname:'item_name', label:'Item Name', read_only:1, in_list_view:1},
                                            {fieldtype:'Float', fieldname:'qty', label:'Qty', in_list_view:1},
                                            {fieldtype:'Data', fieldname:'uom', label:'UOM', read_only:1, in_list_view:1}
                                        ]
                                    }
                                ],

                                primary_action_label: __('Add to Shipment'),

                                primary_action(values) {

                                    let selected = (values.items || []).filter(
                                        row => row.select && row.qty > 0
                                    );

                                    if (!selected.length) {
                                        frappe.msgprint(__('Please select at least one item'));
                                        return;
                                    }

                                    selected.forEach(row => {

                                        let child = frm.add_child("custom_shipment_box");

                                        child.item_code = row.item_code;
                                        child.item_description = row.description;
                                        child.qty = row.qty;
                                        child.uom = row.uom;
                                        child.packed = 0;
                                        child.gross_weight = 0;
                                        child.net_weight = 0;

                                    });

                                    frm.refresh_field("custom_shipment_box");

                                    dialog.hide();
                                }
                            });

                            dialog.show();
                        }
                    });
                },

                __('Select Purchase Order'),
                __('Fetch Items')
            );

        });

    }
});
